#include "Halide.h"

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "gesummv.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A, B, x and scalars alpha, beta exactly as in the
 * original PolyBench C version.
 *
 * C layout:
 *   A[i][j], B[i][j] with i as row, j as column.
 *
 * Halide layout:
 *   Buffer<num_t,2> A(j, i)
 *   Buffer<num_t,2> B(j, i)
 *   Buffer<num_t,1> x(i)
 *
 * i is the slow (row) dimension, j is the fast (column) dimension.
 */
static
void init_array(int n,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B,
                Halide::Buffer<num_t, 1> x) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    Func init_A("init_A"), init_B("init_B"), init_x("init_x");

    // x[i] = (i % n) / n;
    init_x(i) = cast<num_t>(i % n) / cast<int>(n);

    // A[i][j] = ((i * j + 1) % n) / n;
    // Stored as A(j, i) in the Buffer.
    init_A(j, i) = cast<num_t>((i * j + 1) % n) / cast<int>(n);

    // B[i][j] = ((i * j + 2) % n) / n;
    // Stored as B(j, i) in the Buffer.
    init_B(j, i) = cast<num_t>((i * j + 2) % n) / cast<int>(n);

    init_x.realize(x);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers:
    //  - A, B are N x N matrices, stored as (j, i) = (column, row)
    //  - x, y are N-length vectors.
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 2> B(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);

    // ImageParams for A, B, x to feed into the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Initialize data.
    init_array(n, &alpha, &beta, A, B, x);

    // Bind Buffers to ImageParams.
    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // Halide vars and reduction domain.
    Var i("i");
    // j runs over columns (fast dimension, contiguous in memory).
    RDom j(0, A_param.dim(0).extent(), "j");

    // ------------------------------------------------------------------
    // Original math:
    //
    //   tmp[i]   = sum_j A[i][j] * x[j]
    //   y_acc[i] = sum_j B[i][j] * x[j]
    //   y[i]     = alpha * tmp[i] + beta * y_acc[i]
    //
    // A and B are both accessed with the same (i, j) and share x[j],
    // so doing two separate reductions would walk the same data twice.
    //
    // Optimization:
    //   Fuse the two reductions into a single Tuple-valued reduction:
    //     accum(i) = { tmp[i], y_acc[i] }
    //
    //   This halves the number of passes over A, B, and x, improving
    //   memory locality and bandwidth usage. The final y[i] is then
    //   formed from the two tuple components.
    // ------------------------------------------------------------------

    // accum(i)[0] accumulates A(i, j) * x(j)
    // accum(i)[1] accumulates B(i, j) * x(j)
    Func accum("accum");
    accum(i) = Tuple(
        cast<num_t>(0),  // tmp[i] initial value
        cast<num_t>(0)   // y_acc[i] initial value
    );

    // Tuple-valued update over j.
    {
        Expr tmp_old   = accum(i)[0];
        Expr yacc_old  = accum(i)[1];

        Expr a_ij = A_param(j, i);
        Expr b_ij = B_param(j, i);
        Expr x_j  = x_param(j);

        Expr tmp_new  = tmp_old  + a_ij * x_j;
        Expr yacc_new = yacc_old + b_ij * x_j;

        accum(i) = Tuple(tmp_new, yacc_new);
    }

    // Final combination y[i] = alpha * tmp[i] + beta * y_acc[i]
    Func y_func("y_func");
    y_func(i) = Expr(alpha) * accum(i)[0] + Expr(beta) * accum(i)[1];

    // ------------------------------------------------------------------
    // Scheduling
    //
    // Goals:
    //   - Parallelize over i (rows): each output element y[i] is
    //     independent.
    //   - Vectorize over j (columns): j is the fast/contiguous
    //     dimension in A, B, and x, so vectorizing over j gives
    //     coalesced loads and good use of SIMD.
    //   - Keep the schedule simple and robust for arbitrary N.
    // ------------------------------------------------------------------

    Target target = get_jit_target_from_environment();
    const int vec_j = natural_vector_size<num_t>(target);

    // Compute the full accum vector at root; parallelize across rows.
    accum
        .compute_root()
        .parallel(i);

    // For the reduction update:
    //  - Make j the innermost loop (to get contiguous memory access).
    //  - Vectorize across j to exploit SIMD on A, B, and x.
    accum.update()
        .reorder(j, i)       // inner: j, outer: i
        .vectorize(j, vec_j);

    // y_func is a cheap, embarrassingly parallel post-processing step.
    // Parallelize across i; vectorization here is optional, but cheap.
    y_func
        .compute_root()
        .parallel(i)
        .vectorize(i, vec_j);

    // Compile the kernel to machine code with the chosen target.
    y_func.compile_jit(target);

    // Measure execution time (only the kernel run is timed).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel.
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination and allow checking).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; idx++) {
            std::cerr << y(idx) << '\n';
        }
    }

    // Print timing in seconds on stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
