    // -----------------------
    // Scheduling for init
    // -----------------------
    // Use the host JIT target so that natural_vector_size() matches
    // what Halide will JIT-compile for.
    Target init_target = get_jit_target_from_environment();
    const int vec_width = init_target.natural_vector_size(type_of<num_t>());

    // Compute all three initializers at root so we can parallelize them.
    init_x.compute_root();
    init_A.compute_root();
    init_B.compute_root();

    // Parallelize across rows (i = slow dimension).
    init_x.parallel(i);
    init_A.parallel(i);
    init_B.parallel(i);

    // Vectorize across columns (j = fast, contiguous dimension) for the
    // two matrices. This gives good memory coalescing when filling A/B.
    if (vec_width > 1) {
        init_A.vectorize(j, vec_width);
        init_B.vectorize(j, vec_width);
    }

    // Realize into the provided Buffers.
    init_x.realize(x);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers:
    //  - A, B are N x N matrices, stored as (j, i) = (column, row)
    //  - x, y are N-length vectors.
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 2> B(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);

    // ImageParams for A, B, x to feed into the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Initialize data.
    init_array(n, &alpha, &beta, A, B, x);

    // Bind Buffers to ImageParams.
    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // Determine a reasonable vector width for this machine and type.
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Halide vars and reduction domain.
    Var i("i");
    // j runs over columns (fast dimension of A/B and x).
    RDom j(0, A.dim(0).extent(), "j");

    // We implement:
    //   y[i] = alpha * sum_j A[i][j] * x[j]
    //        + beta  * sum_j B[i][j] * x[j]
    //
    // Using a single reduction over j for better locality:
    // we touch A(j,i), B(j,i) and x(j) only once per (i,j) pair.
    Func y_func("y_func");

    // Pure definition: initialize the accumulator to 0.
    y_func(i) = Expr((num_t)0);

    // Reduction definition over j: accumulate contributions from both A and B.
    Expr xj      = x_param(j);
    Expr alpha_e = Expr(alpha);
    Expr beta_e  = Expr(beta);

    y_func(i) += alpha_e * A_param(j, i) * xj +
                 beta_e  * B_param(j, i) * xj;

    // -----------------------
    // Scheduling for kernel
    // -----------------------
    //
    // Memory layout is (j, i): j is contiguous, i has large stride.
    // For each row i we stream sequentially across j, which is good
    // for cache and prefetching. The main opportunity is to:
    //   - parallelize across rows i on the CPU thread pool
    //   - keep j as the innermost loop to maintain unit-stride access
    //     to A, B, and x.
