    //   for io:
    //     for ii:
    //       y_func(i) = 0    (pure step, once per i)
    //       for j:
    //         y_func(i) += ...
    //
    // j remains fully innermost, so accesses to A_param(j,i),
    // B_param(j,i) and x_param(j) are contiguous in memory.

    // Compile the kernel to machine code for the selected target.
    y_func.compile_jit(target);

