 * Halide layout:
 *   Buffer<num_t,2> A(j, i)
 *   Buffer<num_t,2> B(j, i)
 *   Buffer<num_t,1> x(i)
 *
 * i is the slow (row) dimension, j is the fast (column) dimension.
 */
static
void init_array(int n,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B,
                Halide::Buffer<num_t, 1> x) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    Func init_A("init_A"), init_B("init_B"), init_x("init_x");

    Expr n_expr = Expr(n);

    // x[i] = (i % n) / n;
    // 1-D, we parallelize across i.
    init_x(i) = cast<num_t>(i % n) / cast<num_t>(n_expr);

    // A[i][j] = ((i * j + 1) % n) / n;
    // Stored as A(j, i) in the Buffer so that j is the innermost (contiguous) dimension.
    init_A(j, i) = cast<num_t>((i * j + 1) % n) / cast<num_t>(n_expr);

    // B[i][j] = ((i * j + 2) % n) / n;
    // Stored as B(j, i) in the Buffer.
    init_B(j, i) = cast<num_t>((i * j + 2) % n) / cast<num_t>(n_expr);

    // --- Initialization schedule ---
    // x: parallelize over i (independent elements).
    init_x.compute_root()
          .parallel(i);

    // A, B: 2-D, with j contiguous. Parallelize over i (rows) and
    // vectorize across j (columns) to get wide, contiguous loads/stores.
    const int vec_width = 8;  // reasonable width for modern x86; tail is handled by Halide
    init_A.compute_root()
          .parallel(i)
          .vectorize(j, vec_width);

    init_B.compute_root()
          .parallel(i)
          .vectorize(j, vec_width);
    // -------------------------------

    init_x.realize(x);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers:
    //  - A, B are N x N matrices, stored as (j, i) = (column, row)
    //  - x, y are N-length vectors.
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 2> B(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);

    // ImageParams for A, B, x to feed into the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Initialize data.
    init_array(n, &alpha, &beta, A, B, x);

    // Bind Buffers to ImageParams.
    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // Halide vars and reduction domain.
    Var i("i");
    // j runs over columns (fast dimension, contiguous in memory)
    RDom j(0, A.dim(0).extent(), "j");

    // Optimized GESUMMV pipeline:
    // For each row i, compute two dot products in a single reduction:
    //   s0(i) = sum_j A[i][j] * x[j]
    //   s1(i) = sum_j B[i][j] * x[j]
    // Then:
    //   y[i] = alpha * s0(i) + beta * s1(i)
    //
    // We represent (s0, s1) as a Tuple so that we:
    //   - load x(j), A(j,i), B(j,i) once per (i,j)
    //   - do both accumulations in one inner loop for better locality.
    Func sums("sums"), y_func("y_func");

    // Initialize tuple-valued reduction: (0, 0) for each i.
    sums(i) = Tuple(cast<num_t>(0), cast<num_t>(0));

    // Reduction over j: accumulate contributions from A and B simultaneously.
    sums(i) += Tuple(A_param(j, i) * x_param(j),
                     B_param(j, i) * x_param(j));

    // Final combination.
    Expr sA = sums(i)[0];
    Expr sB = sums(i)[1];
    y_func(i) = Expr(alpha) * sA + Expr(beta) * sB;

    // ---------------- Kernel schedule ----------------
    // The heavy work is the reduction in 'sums'. Each row i is independent,
    // so we parallelize across i. Within each reduction, j iterates over the
    // contiguous (column) dimension, which gives good spatial locality in A,B,x.
    sums.compute_root();

    // Parallelize rows; each thread handles a subset of i.
    sums.update().parallel(i);

    // Optionally vectorize across the contiguous reduction dimension j to
    // generate vectorized loads/FMA over the columns.
    const int red_vec_width = 8;
    sums.update().vectorize(j, red_vec_width);

    // y_func is a simple pointwise transform of the already-computed sums.
    // We compute it at root and parallelize + vectorize across i; here i
    // indexes contiguous elements in the 1D buffers backing the Tuple fields.
    Var io("io"), ii("ii");
    y_func.compute_root()
          .split(i, io, ii, 128)   // tile rows into chunks of 128
          .parallel(io)            // parallel over tiles
          .vectorize(ii, 8);       // vectorize within a tile
    // -------------------------------------------------

    // Compile the kernel to machine code.
    y_func.compile_jit();

    // Measure execution time.
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel.
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination and allow checking).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; idx++) {
            std::cerr << y(idx) << '\n';
        }
    }

    // Print timing in seconds on stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
