    //
    // Remember: A and B are stored as (j, i) in the Buffer.
    Func tmp("tmp"), y_acc("y_acc"), y_func("y_func");

    // Initialize reductions.
    tmp(i)   = cast<num_t>(0);
    y_acc(i) = cast<num_t>(0);

    // Reduction over j (columns).
    tmp(i)   += A_param(j, i) * x_param(j);
    y_acc(i) += B_param(j, i) * x_param(j);

    // Final combination.
    y_func(i) = Expr(alpha) * tmp(i) + Expr(beta) * y_acc(i);

    // ------------------------------------------------------------------
    // Scheduling
    // ------------------------------------------------------------------
    //
    // Data layout and access pattern:
    //   - A_param and B_param are Buffers of size (n, n) with index order (j, i).
    //   - For a fixed row i, we iterate j from 0..n-1, so we walk A_param(j, i)
    //     and B_param(j, i) along their contiguous (stride-1) dimension.
    //   - x_param(j) is also 1-D and contiguous in j.
    //
    // This already gives us very good cache and memory locality along j.
    //
    // The heavy computation is entirely separable across rows i:
    //   each i computes an independent dot product over j.
    // We exploit this by parallelizing across i. We keep the j loop
    // serial within each worker thread so that all loads stay unit-stride.
    //
    // We do *not* change the mathematical structure of the computation,
    // so floating-point rounding behavior is preserved up to the same
    // associativity as the original i-outer / j-inner loops.

    // Parallelize the outermost loop over i (rows) of the final stage.
    // tmp and y_acc are inlined into y_func and will be computed
    // inside this parallel loop; there is no cross-i dependence, so
    // this is race-free.
    y_func.compute_root()
          .parallel(i);

    // Unroll the inner reduction loop a small amount to expose some
    // instruction-level parallelism, while still handling arbitrary N.
    // This affects the generated code inside each thread only.
    tmp.update().unroll(j, 4);
    y_acc.update().unroll(j, 4);

    // Compile the kernel to machine code.
    Target target = get_jit_target_from_environment();
    y_func.compile_jit(target);

    // Measure execution time (kernel only).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel.
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination and allow checking).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; idx++) {
            std::cerr << y(idx) << '\n';
        }
    }

    // Print timing in seconds on stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
